fn cell(rows: List[Str], r: Int, c: Int) -> Str {
  return rows.get_or(r, "").slice(c, c + 1)
}

fn no_repeat(cells: List[Str]) -> Bool {
  let digits = cells.filter(fn(ch) => ch != ".")
  return digits.unique().len() == digits.len()
}

pub fn sudoku(rows: List[Str]) -> Bool {
  if rows.len() != 9 {
    return false
  }
  let shape_ok = rows.all(fn(row) => row.len() == 9 and row.chars().all(fn(ch) => "123456789.".contains(ch)))
  if not shape_ok {
    return false
  }
  let idx = range(0, 9)
  let row_groups = idx.map(fn(r) => idx.map(fn(c) => cell(rows: rows, r: r, c: c)))
  let col_groups = idx.map(fn(c) => idx.map(fn(r) => cell(rows: rows, r: r, c: c)))
  let box_groups = idx.map(fn(b) => idx.map(fn(k) => cell(rows: rows, r: (b / 3) * 3 + k / 3, c: (b % 3) * 3 + k % 3)))
  let all_groups = row_groups.concat(col_groups).concat(box_groups)
  return all_groups.all(fn(g) => no_repeat(g))
}
